"""Network contacts: sourced direct phones, one map, and an explicit demo form."""
import json,re
from hotel_details import DETAILS

EMAIL='m-br-1@turris-management.ru'
def render(p,g):
 a,e,image,icon,ext,url=[g[k] for k in ['a','e','image','icon','ext','url']]
 hotels=g['HOTELS'];geo=g['MAP']['hotels']
 copy_svg='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="3" width="12" height="15" rx="2"/><path d="M16 18v3H4V7h4"/></svg>'
 mail_svg='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m3 5 9 8 9-8"/></svg>'
 def copy(value,label):return '<button type="button" class="ct-copy" data-contact-copy="'+e(value)+'" aria-label="'+e(label)+'" title="'+e(label)+'">'+copy_svg+'</button>'
 def address(h):return '<div class="ct-address">'+icon('pin')+'<span>Москва, '+h['address']+'</span>'+copy('Москва, '+h['address'],'Скопировать адрес '+h['full'])+'</div>'
 def phone(hid):return '<a class="ct-admin-phone" href="tel:'+re.sub(r'[^+\d]','',DETAILS[hid]['admin'])+'">'+icon('phone')+DETAILS[hid]['admin']+'</a>'
 def route(hid):return geo[hid]['source']+'?rtext=~'+str(geo[hid]['lat'])+','+str(geo[hid]['lng'])
 notes={'tverskaya':'У Белорусского вокзала','lubyansky':'Бесплатная парковка. Наличие места и въезд уточните заранее.','petrovsky':'На Петровском бульваре','tagansky':'В отеле нет лифта. Уточните этаж до приезда.'}
 hero='<section class="ct-hero"><div><div class="eyebrow">Туррис · Москва</div><h1>Контакты отелей<br><em>Туррис в Москве</em></h1><p class="ct-intro">Поможем с бронированием, проживанием и дорогой до отеля.</p><div class="ct-hero-links"><a href="#map">Найти свой отель ↓</a><a href="#write-us">Написать нам ↓</a></div><p class="ct-hint">По вопросам заселения и проезда — администратор выбранного отеля.</p></div><aside class="ct-booking"><div class="eyebrow">Отдел бронирования</div><a href="tel:88005054455" class="ct-booking-phone">'+icon('phone')+'8 800 505 44 55</a><div class="ct-email">'+mail_svg+'<a href="mailto:'+EMAIL+'">'+EMAIL+'</a>'+copy(EMAIL,'Скопировать email отдела бронирования')+'</div><p>Подбор номера, тарифы и условия поездки.</p>'+a('booking','Подобрать номер '+icon('arrow'),'btn full')+'</aside></section>'
 buttons='';panels='';cards=''
 for n,(hid,h) in enumerate(hotels.items(),1):
  media='<div class="ct-hotel-photo">'+image(hid,'Фасад отеля '+h['full'],sizes='(max-width:640px) calc(100vw - 32px), 590px')+'</div>'
  buttons+='<button type="button" class="map-choice" data-map-select="'+hid+'" aria-pressed="false"><span class="map-number">'+str(n).zfill(2)+'</span><span>'+h['name']+'</span>'+icon('chevron')+'</button>'
  panels+='<article class="map-detail" data-map-detail="'+hid+'">'+media+'<div class="ct-map-copy"><h3>'+h['name']+'</h3>'+address(h)+'<span class="ct-label">Администратор отеля</span>'+phone(hid)+ext(route(hid),'Построить маршрут','btn ct-blue full')+a(hid+'_contacts','Подробнее о проезде '+icon('arrow'),'text-link')+'</div></article>'
  cards+='<article class="ct-card" id="contact-'+hid+'"><a class="ct-card-image" href="'+url(hid)+'">'+image(hid,'Фасад отеля '+h['full'],sizes='(max-width:640px) calc(100vw - 32px), 590px')+'</a><div class="ct-card-copy"><h3>'+a(hid,h['name'])+'</h3>'+address(h)+'<span class="ct-label">Администратор отеля</span>'+phone(hid)+'<p class="ct-location">'+icon('document' if hid=='tagansky' else 'pin')+notes[hid]+'</p><div class="ct-card-actions"><a class="btn ct-outline" href="tel:'+re.sub(r'[^+\d]','',DETAILS[hid]['admin'])+'">'+icon('phone')+'Позвонить</a>'+ext(route(hid),'Построить маршрут','btn ct-blue')+'</div><div class="ct-card-links">'+a(hid+'_contacts','Как добраться '+icon('arrow'),'text-link')+a(hid+'_rooms','Номера и цены '+icon('arrow'),'text-link')+'</div></div></article>'
 config={hid:dict(geo[hid],name=h['name']) for hid,h in hotels.items()}
 maphtml='<section class="ct-section"><h2>Четыре отеля на карте</h2><p class="ct-intro">Выберите адрес — покажем контакт и маршрут.</p><div class="hotel-map ct-map" id="map" data-hotel-map data-selected="tverskaya" data-tile-url="'+g['MAP']['tile_url']+'"><div class="map-choices" aria-label="Выберите отель">'+buttons+'</div><div class="map-layout"><div class="map-stage"><div class="map-canvas" data-map-canvas role="region" aria-label="Карта четырёх отелей Туррис в Москве"></div><div class="map-toolbar"><span>Москва · четыре адреса</span><button type="button" data-map-reset>Все отели '+icon('pin')+'</button></div><p class="map-status" data-map-status role="status">Загружаем карту… Контакты и маршруты доступны рядом.</p></div><div class="map-details">'+panels+'</div></div><span class="sr-only" data-map-announcement aria-live="polite"></span><script type="application/json" data-map-config>'+json.dumps(config,ensure_ascii=False)+'</script></div></section>'
 catalogue='<section class="ct-section" id="hotel-contacts"><h2>Связаться с вашим отелем</h2><p class="ct-intro">Администратор поможет с заселением и деталями приезда.</p><div class="ct-cards">'+cards+'</div></section>'
 topics=[('calendar','У меня есть бронь','Подготовьте номер подтверждения и даты. Изменения и отмена зависят от тарифа.','manage','Моя бронь'),('document','Поездка от компании','Сообщите данные плательщика и требования к документам до оплаты.','business','Для компаний'),('guest','Группа или долгий срок','Укажите даты, количество гостей и номеров для расчёта.','groups','Запросить расчёт')]
 topics_html='<section class="ct-section"><h2>По какому вопросу вы обращаетесь?</h2><div class="ct-topics">'+''.join('<article>'+icon(ic)+'<div><h3>'+h+'</h3><p>'+text+'</p>'+a(dest,label+' '+icon('arrow'),'text-link')+'</div></article>' for ic,h,text,dest,label in topics)+'</div></section>'
 options='<option value="">Помогите выбрать</option>'+''.join('<option value="'+hid+'">'+h['name']+'</option>' for hid,h in hotels.items())
 form='<section class="ct-write" id="write-us"><div><h2>Напишите нам</h2><p class="ct-intro">Выберите отель и тему — так проще объяснить ваш вопрос.</p><div class="ct-write-email">'+mail_svg+'<div><span>Можно написать на почту</span><a href="mailto:'+EMAIL+'">'+EMAIL+'</a></div></div></div><div class="ct-form-panel"><form data-contact-form novalidate><fieldset disabled><legend class="sr-only">Обращение в отель</legend><div class="ct-form-grid"><label>Тема обращения<select name="topic"><option>Общий вопрос</option><option>У меня есть бронь</option><option>Приезд и заселение</option><option>Поездка от компании</option><option>Группа или долгий срок</option></select></label><label>Отель<select name="hotel">'+options+'</select></label><label>Ваше имя<input name="name" autocomplete="name" placeholder="Как к вам обращаться" maxlength="100"></label><label>Телефон или email <span aria-hidden="true">*</span><input name="contact" autocomplete="email" placeholder="Удобный контакт для ответа" required maxlength="150" aria-describedby="contact-error"></label><label class="ct-wide">Сообщение <span aria-hidden="true">*</span><textarea name="message" placeholder="Расскажите, чем можем помочь" required minlength="10" maxlength="3000" rows="3"></textarea></label></div><label class="ct-consent"><input type="checkbox" name="consent" required><span>Согласен на обработку персональных данных. '+a('privacy','Политика конфиденциальности')+'</span></label><p class="ct-form-note">Демонстрационная форма: сообщение не отправляется. Для связи используйте телефон или email.</p><p id="contact-error" class="ct-error" role="alert"></p><button type="submit" class="btn full">Отправить сообщение '+icon('arrow')+'</button></fieldset></form><noscript><p>Для связи позвоните 8 800 505 44 55 или напишите на '+EMAIL+'. Интерактивная форма работает с JavaScript.</p></noscript><section class="ct-result" data-contact-result hidden tabindex="-1" role="status"><div class="eyebrow">Демонстрация формы</div><h3>Сообщение не отправлено</h3><p data-contact-result-text></p><p>Для настоящего обращения позвоните в отель или напишите на почту отдела бронирования.</p><a href="mailto:'+EMAIL+'" class="text-link">'+EMAIL+'</a><button type="button" class="btn ct-outline" data-contact-again>Вернуться к форме</button></section></div></section>'
 faq_items=[('Куда звонить, если я уже еду в отель?','Позвоните администратору выбранного отеля. Прямой номер указан в его карточке выше.',None),('Как уточнить парковку и вход?','Свяжитесь с администратором до поездки: уточните наличие места, въезд и удобный вход. В Таганском нет лифта.',None),('Можно ли заехать раньше или выехать позже?','Ранний заезд и поздний выезд согласуются с отелем и зависят от наличия номеров и выбранного тарифа.','help_checkin'),('Как изменить или отменить бронирование?','Подготовьте номер подтверждения и даты поездки. Возможность изменения и условия отмены указаны в вашем тарифе.','manage')]
 faq='<section class="ct-bottom"><div><h2>Перед приездом</h2>'+g['faqs'](faq_items)+'</div><aside><h2>Документы и условия</h2><div class="ct-docs">'+''.join(a(dest,icon('document')+label+icon('arrow')) for dest,label in [('legal','Реквизиты и правовая информация'),('help_checkin','Правила проживания'),('payment','Условия оплаты')])+'</div></aside></section>'
 return '<div class="wrap contacts-page">'+hero+maphtml+catalogue+topics_html+form+faq+'<p class="ct-copy-status" data-contact-copy-status role="status" aria-live="polite"></p></div>'
